function _fcc_templateString($value) {
    return {
        $value,
        $type: 'template-string',
    };
}
function _fcc_object($value) {
    return {
        $value,
        $type: 'object',
        ...$value,
    };
}
function _fcc_renderHtmlValue(value) {
    // If the value is an array, then it's an array of objects representing React
    // children (either of type INSTANCE for pills, or CODE for inline code). The
    // template string handler in the template API handles extracting the instance
    // objects in a way the UI can handle.
    const isComponentArray = Array.isArray(value);
    if (isComponentArray) {
        return figma.html `${value}`;
    }
    if (typeof value === 'object') {
        return JSON.stringify(value);
    }
    else if (typeof value === 'undefined') {
        return '';
    }
    else {
        return value.toString();
    }
}
function _fcc_renderHtmlAttribute(name, value) {
    // figma.boolean returns undefined instead of false in some cases
    if (typeof value === 'undefined') {
        return '';
    }
    else if (typeof value === 'boolean') {
        if (value) {
            return name;
        }
        else {
            return '';
        }
    }
    else if (typeof value === 'string' || typeof value === 'number' || typeof value === 'bigint') {
        return `${name}="${value.toString().replaceAll('\n', '\\n').replaceAll('"', '\\"')}"`;
    }
    else if (value.$type === 'identifier') {
        return `${name}="${value.$value}"`;
    }
    else {
        // TODO make this show a proper error in the UI
        return `${name}="Code Connect Error: Unsupported type '${typeof value}' for attribute"`;
    }
}
function _fcc_identifier($value) {
    return {
        $value,
        $type: 'identifier',
    };
}

const figma = require('figma')

const className = ["uif-tab"].filter(v => !!v).join(' ')
const selected = figma.currentLayer.__properties__.boolean('Selected', {
"true": 'true',
"false": 'false'})
const label = figma.currentLayer.__properties__.string('Label')
const __props = {}
if (className && className.type !== 'ERROR') {
  __props["className"] = className
}
if (selected && selected.type !== 'ERROR') {
  __props["selected"] = selected
}
if (label && label.type !== 'ERROR') {
  __props["label"] = label
}

export default figma.html`<button ${_fcc_renderHtmlAttribute('class', className)} role="tab" type="button" ${_fcc_renderHtmlAttribute('aria-selected', selected)}>${_fcc_renderHtmlValue(label)}</button>`
